from pathlib import Path
from html import escape
root=Path(__file__).parent
pages={
'privacy': {
 'title':'Privacy policy', 'intro':'How Event Horizon handles information.',
 'sections':[
 ('operator','Who we are','''<p>Event Horizon is the publishing name of João Seixas. This policy covers this website and our apps that link to it. For privacy questions or requests, use our <a href="/support/">support contact</a>.</p>'''),
 ('data','Information and services','''<p><strong>On your devices.</strong> Our apps store the information you enter or import, your preferences and saved activity on your devices. Some features exchange data with your paired devices. Device backups are controlled by your platform settings. We do not receive this local information unless you choose to send it to us.</p><p><strong>Connected services.</strong> When you use a feature that connects to an external service or device, it receives the information needed to fulfil your request, such as your IP address, requested content and any credentials you provide. Independent services handle that information under their own privacy policies. Review information before sharing it.</p><p><strong>This website.</strong> We do not add advertising, analytics or tracking cookies. Our planned host, GitHub Pages, logs visitor IP addresses for security. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy statement</a>.</p><p><strong>Contacting us.</strong> We receive your email address, message and any attachments through our email provider and use them to handle your request. This is based on our legitimate interest in providing support, or on performing our agreement with you or complying with a legal obligation where applicable. Please do not send passwords, access tokens or unnecessary sensitive information.</p>'''),
 ('retention','Storage and retention','''<p>Local data remains until removed through the app or device controls, or replaced or cleared by the app. Uninstalling an app may not remove information in device secure storage, backups or copies you have shared.</p><p>We keep support correspondence only for handling your request, necessary follow-up and applicable legal obligations. External services control their own retention. We do not sell personal information or use support messages for advertising.</p>'''),
 ('rights','Your rights','''<p>Depending on applicable law, you may request access, correction, erasure, restriction or portability of information we hold, or object to processing based on legitimate interests. Where consent is the basis, you may withdraw it. Contact us through <a href="/support/">support</a>. We cannot remotely retrieve or erase records held only on your devices or by an independent service.</p><p>You have the right to lodge a complaint with your local data protection authority.</p>'''),
 ('changes','Updates','''<p>We will update this policy when our practices change, show the effective date and communicate material changes appropriately.</p>''') ]},
 'terms': {
 'title':'Terms & conditions', 'intro':'Using Event Horizon’s website and apps.',
 'sections':[
 ('operator','About these terms','''<p>Event Horizon is the publishing name of João Seixas. These terms cover this website and our apps that link to them. For questions, use our <a href="/support/">support contact</a>. Information handling is explained in our <a href="/privacy/">privacy policy</a>.</p>'''),
 ('licence','Licences and permitted use','''<p>Apps downloaded from the App Store are subject to Apple’s <a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/">Standard End User Licence Agreement</a> unless a custom licence is supplied. These terms do not replace that licence. Open-source software retains its own licence and the rights it grants.</p><p>Use our website and apps lawfully and respect others’ rights. You are responsible for having permission to access or share the content you supply. Do not misuse services or attempt unauthorised access. Our software does not grant rights to third-party content or subscriptions.</p>'''),
 ('services','Third-party services and availability','''<p>External services have their own terms and availability. App compatibility and features may change; we will provide updates and notices where required by law or our agreement with you. Keep backups of important information.</p>'''),
 ('rights','Purchases and your rights','''<p>Any price or subscription conditions are shown before purchase. Apple handles App Store transactions; manage subscriptions through your Apple account and <a href="https://reportaproblem.apple.com/">request refunds through Apple</a>.</p><p>Nothing here limits mandatory consumer rights, statutory guarantees, remedies or liability that cannot lawfully be excluded. Applicable law and the relevant app licence govern responsibility for defects and loss.</p>'''),
 ('changes','Changes and contact','''<p>We will date changes to these terms and communicate material changes appropriately. Changes do not retrospectively remove accrued rights. Contact <a href="/support/">support</a> about any questions or problems.</p>''') ]},
 'support': {
 'title':'Support', 'intro':'Help with our apps and privacy requests.',
 'sections':[
 ('contact','Contact','''<p class="support-intro">event.horizon.gg@outlook.com</p><p class="pending">This inbox is being created. Email links will be enabled when it is ready.</p><p>For app support, include the app name, version and a short description of the problem. Use the same address for privacy questions or requests about your information.</p><p>Please do not send passwords, private source URLs, access tokens or unnecessary sensitive information.</p>''') ]}
}
for slug,p in pages.items():
 nav=''.join(f'<a href="/{s}/"'+(' aria-current="page"' if s==slug else '')+f'>{label}</a>' for s,label in [('support','Support'),('privacy','Privacy'),('terms','Terms')])
 body=''.join(f'<section id="{key}"><h2>{escape(title)}</h2>{copy}</section>' for key,title,copy in p['sections'])
 draft='' if slug=='support' else '<aside class="draft" aria-label="Draft status">Review draft. Contact details and remaining privacy disclosures must be completed before publication.</aside>'
 html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#030303"><meta name="robots" content="noindex,nofollow"><title>{escape(p['title'])} · Event Horizon</title><meta name="description" content="{escape(p['intro'],quote=True)}"><link rel="icon" href="/assets/logo.png"><link rel="stylesheet" href="/legal.css"><link rel="stylesheet" href="/brand.css"></head>
<body><a class="skip" href="#content">Skip to content</a><header class="page-header"><a class="brand" href="/" aria-label="Event Horizon home"><img src="/assets/logo.png" width="50" height="50" alt=""><span class="brand-wordmark" aria-hidden="true"><img src="/assets/eventhorizon-original.png" alt="" width="1536" height="1024"></span></a><nav aria-label="Main navigation">{nav}</nav></header>
<main id="content"><p class="eyebrow">Event Horizon / {'Support' if slug=='support' else 'Legal'}</p><h1>{escape(p['title'])}</h1><p class="lede">{escape(p['intro'])}</p>{'<p class="date">Review draft · 25 November 2026</p>' if slug!='support' else ''}{draft}<div class="copy">{body}</div></main>
<footer class="page-footer"><span>© 2026 Event Horizon</span><nav aria-label="Footer">{nav}</nav></footer></body></html>'''
 (root/'dist'/slug/'index.html').write_text(html)
